@layer cyn.recipes {
  .with-sidebar {
    display: flex;
    flex-wrap: wrap;
    gap: var(--cyn-sidebar-gap, 1.5rem);
  }
  .sidebar {
    flex-basis: var(--cyn-sidebar-width, 16rem);
    flex-grow: 1;
  }
  .main-content {
    flex-basis: 0;
    flex-grow: 999;
    min-inline-size: 50%;
  }
}
